
.mx-inline {
  width: 100%; max-width: 420px; margin: 6px auto;
  font-family: var(--font-main); font-size: 12px; user-select: none;
  background: var(--t-surface, #f5f0e8); border: 1px solid var(--t-border, rgba(0,0,0,0.08));
  border-radius: 10px; overflow: hidden;
}
.mx-bar {
  display: flex; align-items: center; gap: 6px; padding: 6px 12px; cursor: pointer;
  border-left: 2px solid transparent; transition: all 0.15s;
  &:hover { background: rgba(0,0,0,0.04); border-left-color: #c9a96e; }
}
.mx-bar-icon { font-size: 10px; color: #c9a96e; }
.mx-bar-title { font-weight: 600; font-size: 11px; color: #8b7355; letter-spacing: 2px; flex: 1; }
.mx-bar-arrow { font-size: 9px; color: #b8a898; }

.mirror-panel {
  --m-accent: #c47b8b; --m-accent-dim: rgba(196,123,139,0.2); --m-glow: rgba(196,123,139,0.15); --m-surface: #faf5f5;
  padding: 4px 8px 8px;
  &.theme-teal { --m-accent: #5ea0a7; --m-accent-dim: rgba(94,160,167,0.2); --m-glow: rgba(94,160,167,0.12); --m-surface: #f4f8f9; }
}
.mirror-frame {
  position: relative; border-radius: 16px; padding: 6px;
  background: linear-gradient(145deg, #8b7355, #6b5a48 25%, #c9a96e 50%, #6b5a48 75%, #8b7355);
  box-shadow: 0 0 40px var(--m-glow), 0 4px 20px rgba(0,0,0,0.3);
}
.frame-ring { position: absolute; inset: 6px; border-radius: 13px; border: 1px solid rgba(201,169,110,0.3); pointer-events: none; }
.frame-inset { position: absolute; inset: 10px; border-radius: 11px; border: 1px solid rgba(201,169,110,0.15); pointer-events: none; }
.mirror-surface {
  position: relative; z-index: 1; border-radius: 11px; padding: 14px 12px 10px;
  background: radial-gradient(ellipse at center, var(--m-surface), #ede6d8); overflow: hidden;
}
.mirror-mist { position: absolute; border-radius: 50%; filter: blur(30px); opacity: 0.08; pointer-events: none; }
.mist-1 { width: 120px; height: 80px; background: var(--m-accent); top: -20px; right: -30px; }
.mist-2 { width: 100px; height: 60px; background: #c9a96e; bottom: 10px; left: -20px; }
.panel-title { text-align: center; font-size: 20px; font-weight: 700; letter-spacing: 8px; color: #4a4035; position: relative; z-index: 1; }
.panel-sub { text-align: center; font-size: 10px; color: var(--m-accent); letter-spacing: 3px; margin-bottom: 10px; position: relative; z-index: 1; }
.direction-toggle { display: flex; align-items: center; justify-content: center; gap: 8px; margin-bottom: 8px; position: relative; z-index: 1; }
.toggle-btn { background: none; border: none; font-family: inherit; font-size: 10px; color: #8a7e6e; cursor: pointer; letter-spacing: 1px; padding: 2px 6px; transition: color 0.2s;
  &.active { color: var(--m-accent); font-weight: 600; } }
.toggle-track { width: 36px; height: 18px; background: rgba(139,115,85,0.15); border-radius: 9px; cursor: pointer; position: relative; }
.toggle-thumb { width: 14px; height: 14px; border-radius: 50%; background: var(--m-accent); position: absolute; top: 2px; left: 2px; transition: left 0.25s;
  &.toWorld { left: 20px; } }
.btn-random { display: flex; align-items: center; justify-content: center; gap: 6px; width: 100%; padding: 10px 0; margin-bottom: 6px; background: var(--m-accent-dim); border: 1px solid var(--m-accent); border-radius: 8px; cursor: pointer; position: relative; z-index: 1; color: var(--m-accent); font-family: inherit; font-size: 13px; font-weight: 600; letter-spacing: 3px; transition: all 0.2s;
  &:hover { background: var(--m-accent); color: #fff; } }
.btn-icon { font-size: 10px; }
.btn-custom-toggle { display: flex; align-items: center; gap: 6px; width: 100%; padding: 8px 0; background: none; border: 1px dashed rgba(139,115,85,0.2); border-radius: 8px; cursor: pointer; color: #8a7e6e; font-family: inherit; font-size: 11px; letter-spacing: 2px; transition: all 0.2s; position: relative; z-index: 1;
  &:hover { border-color: var(--m-accent); color: var(--m-accent); } }
.custom-form { display: flex; flex-direction: column; gap: 6px; margin-top: 6px; padding: 10px; background: rgba(139,115,85,0.04); border: 1px solid rgba(139,115,85,0.1); border-radius: 8px; }
.form-row { display: flex; flex-direction: column; gap: 3px;
  label { font-size: 9px; color: #8a7e6e; letter-spacing: 1px; }
  select, input { padding: 5px 8px; border-radius: 6px; border: 1px solid rgba(139,115,85,0.15); background: rgba(255,255,255,0.6); color: #4a4035; font-family: inherit; font-size: 11px; outline: none;
    &:focus { border-color: var(--m-accent); } } }
.tag-pool { display: flex; flex-wrap: wrap; gap: 4px; }
.tag { padding: 2px 8px; border-radius: 10px; border: 1px solid rgba(139,115,85,0.15); font-size: 10px; color: #8a7e6e; cursor: pointer; transition: all 0.15s;
  &:hover { border-color: var(--m-accent); }
  &.picked { background: var(--m-accent-dim); border-color: var(--m-accent); color: var(--m-accent); } }
.btn-send { width: 100%; padding: 8px 0; margin-top: 4px; background: var(--m-accent); border: none; border-radius: 8px; cursor: pointer; color: #fff; font-family: inherit; font-size: 12px; font-weight: 600; letter-spacing: 3px; transition: opacity 0.2s;
  &:hover { opacity: 0.85; } }
